import{_ as d,a0 as a,w as s,s as i,ao as u,I as t,x as r,a1 as l,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"假期志愿服务的 4 种方式 | LCTT x X-CMD","titleTemplate":false,"description":"假期志愿服务的 4 种方式 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"假期志愿服务的 4 种方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"假期志愿服务的 4 种方式 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20191220 4 ways to volunteer this holiday season","title":"假期志愿服务的 4 种方式","tag":"202001","desc":""},"relativePath":"202001/20191220 4 ways to volunteer this holiday season.md","filePath":"[post].md"}'),p={name:"202001/20191220 4 ways to volunteer this holiday season.md"};function f(m,o,C,g,b,y){const e=a("Link");return s(),i("div",null,[o[27]||(o[27]=u('<h1 id="假期志愿服务的-4-种方式" tabindex="-1">假期志愿服务的 4 种方式 <a class="header-anchor" href="#假期志愿服务的-4-种方式" aria-label="Permalink to “假期志愿服务的 4 种方式”">​</a></h1><blockquote><p>想要洒播些节日的快乐吗？为开源组织做贡献，帮助有需要的社区。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202001/20/223730f7983z8atxp1tf4l.jpg" alt=""></p><p>当领导者们配置人员和资源以做出积极改变时，就会产生社会影响。但是，许多社会努力都缺乏能够为这些改变者提供服务的技术资源。然而，有些组织通过将想要做出改变的开发人员与迫切需要更好技术的社区和非营利组织联系起来，来促进技术进步。这些组织通常为特定的受众提供服务，并招募特定种类的技术人员，它们有一个共同点：开源。</p><p>作为开发人员，我们出于各种原因试图加入开源社区。有些是为了专业发展，有些是为了能够与广阔的网络上令人印象深刻的技术人员合作，还有其他人则是因为他们清楚自己的贡献对于项目的成功的必要性。为什么不将你作为开发人员的才华投入到需要它的地方，而同时又为开源组织做贡献呢？以下组织是实现此目标的一些主要事例。</p><h3 id="code-for-america" tabindex="-1">Code for America <a class="header-anchor" href="#code-for-america" aria-label="Permalink to “Code for America”">​</a></h3><p>“Code for America” 是在数字时代，政府如何依靠人民为人民服务的一个例子。通过其 Brigade Network，该组织在美国各个城市中组织了一个由志愿程序员、数据科学家、相关公民和设计师组成的全国联盟。这些本地分支机构定期举行聚会，向社区开放。这样既可以向小组推出新项目，又可以协调正在进行的工作。为了使志愿者与项目相匹配，该网站经常列出项目所需的特定技能，例如数据分析、内容创建和JavaScript。同时，Brigade 网站也会关注当地问题，分享自然灾害等共同经验，这些都可以促进成员之间的合作。例如，新奥尔良、休斯敦和坦帕湾团队合作开发了一个飓风响应网站，当灾难发生时，该网站可以快速响应不同的城市灾难情况。</p>',7)),t("p",null,[o[1]||(o[1]=r("想要加入该组织，请访问 ",-1)),l(e,{href:"https://brigade.codeforamerica.org/"},{default:n(()=>[...o[0]||(o[0]=[r("该网站",-1)])]),_:1}),o[2]||(o[2]=r(" 获取 70 多个 Brigade 的清单，以及个人加入组织的指南。",-1))]),o[28]||(o[28]=t("h3",{id:"code-for-change",tabindex:"-1"},[r("Code for Change "),t("a",{class:"header-anchor",href:"#code-for-change","aria-label":"Permalink to “Code for Change”"},"​")],-1)),o[29]||(o[29]=t("p",null,"“Code for Change” 显示了即使在高中时期，也可以为社会做贡献。印第安纳波利斯的一群高中开发爱好者成立了自己的俱乐部，他们通过创建针对社区问题的开源软件解决方案来回馈当地组织。“Code for Change” 鼓励当地组织提出项目构想，学生团体加入并开发完全自由和开源的解决方案。该小组已经开发了诸如“蓝宝石”之类的项目，该项目优化了当地难民组织的志愿者管理系统，并建立了民权委员会的投诉表格，方便公民就他们所关心的问题在网上发表意见。",-1)),t("p",null,[o[4]||(o[4]=r("有关如何在你自己的社区中创建 “Code for Change”，",-1)),l(e,{href:"http://codeforchange.herokuapp.com/"},{default:n(()=>[...o[3]||(o[3]=[r("访问他们的网站",-1)])]),_:1}),o[5]||(o[5]=r("。",-1))]),o[30]||(o[30]=t("h3",{id:"python-for-good-ruby-for-good",tabindex:"-1"},[r("Python for Good/Ruby for Good "),t("a",{class:"header-anchor",href:"#python-for-good-ruby-for-good","aria-label":"Permalink to “Python for Good/Ruby for Good”"},"​")],-1)),o[31]||(o[31]=t("p",null,"“Python for Good” 和 “Ruby for Good” 是在俄勒冈州波特兰市和弗吉尼亚州费尔法克斯市举办的双年展活动，该活动将人们聚集在一起，为各自的社区开发和制定解决方案。",-1)),o[32]||(o[32]=t("p",null,[r("在周末，人们聚在一起聆听当地非营利组织的建议，并通过构建开源解决方案来解决他们的问题。 2017 年，“Ruby For Good” 参与者创建了 “Justice for Juniors”，该计划指导当前和以前被监禁的年轻人，并将他们重新融入社区。参与者还创建了 “Diaperbase”，这是一种库存管理系统，为美国各地的"),t("ruby",null,[r("尿布库"),t("rt",null,"diaper bank")]),r("所使用。这些活动的主要目标之一是将看似不同的行业和思维方式的组织和个人聚集在一起，以谋求共同利益。公司可以赞助活动，非营利组织可以提交项目构想，各种技能的人都可以注册参加活动并做出贡献。通过两岸（美国大西洋和太平洋东西海岸）的努力，“Ruby for Good” 和 “Python for Good” 一直恪守“使世界变得更好”的座右铭。")],-1)),t("p",null,[o[7]||(o[7]=r("“",-1)),l(e,{href:"https://rubyforgood.org/"},{default:n(()=>[...o[6]||(o[6]=[r("Ruby for Good",-1)])]),_:1}),o[8]||(o[8]=r("” 在夏天举行，举办地点在弗吉尼亚州费尔法克斯的乔治•梅森大学。",-1))]),o[33]||(o[33]=t("h3",{id:"social-coder",tabindex:"-1"},[r("Social Coder "),t("a",{class:"header-anchor",href:"#social-coder","aria-label":"Permalink to “Social Coder”"},"​")],-1)),o[34]||(o[34]=t("p",null,"英国的 Ed Guiness 创建了 “Social Coder”，将志愿者和慈善机构召集在一起，为六大洲的非营利组织创建和使用开源项目。“Social Coder” 积极招募来自世界各地的熟练 IT 志愿者，并将其与通过 Social Coder 注册的慈善机构和非营利组织进行匹配。项目范围从简单的网站更新到整个移动应用程序的开发。",-1)),o[35]||(o[35]=t("p",null,"例如，PHASE Worldwide 是一个在尼泊尔支持工作的小型非政府组织，因为 “Social Coder”，它获得了利用开源技术的关键支持和专业知识。",-1)),o[36]||(o[36]=t("p",null,"有许多慈善机构已经与英国的 “Social Coder”进行了合作，也欢迎其它国家的组织加入。通过他们的网站，个人可以注册为社会软件项目工作，找到寻求帮助的组织和慈善机构。",-1)),t("p",null,[o[10]||(o[10]=r("对 “Social Coder” 的志愿服务感兴趣的个人可以 ",-1)),l(e,{href:"https://socialcoder.org/Home/Programmer"},{default:n(()=>[...o[9]||(o[9]=[r("在此",-1)])]),_:1}),o[11]||(o[11]=r("注册.",-1))]),o[37]||(o[37]=t("hr",null,null,-1)),t("p",null,[o[13]||(o[13]=r("via: ",-1)),l(e,{href:"https://opensource.com/article/19/12/ways-volunteer"},{default:n(()=>[...o[12]||(o[12]=[r("https://opensource.com/article/19/12/ways-volunteer",-1)])]),_:1})]),t("p",null,[o[18]||(o[18]=r("作者：",-1)),l(e,{href:"https://opensource.com/users/johnjones4"},{default:n(()=>[...o[14]||(o[14]=[r("John Jones",-1)])]),_:1}),o[19]||(o[19]=r(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...o[15]||(o[15]=[r("lujun9972",-1)])]),_:1}),o[20]||(o[20]=r(" 译者：",-1)),l(e,{href:"https://github.com/Morisun029"},{default:n(()=>[...o[16]||(o[16]=[r("Morisun029",-1)])]),_:1}),o[21]||(o[21]=r(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:n(()=>[...o[17]||(o[17]=[r("wxy",-1)])]),_:1})]),t("p",null,[o[24]||(o[24]=r("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...o[22]||(o[22]=[r("LCTT",-1)])]),_:1}),o[25]||(o[25]=r(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:n(()=>[...o[23]||(o[23]=[r("Linux中国",-1)])]),_:1}),o[26]||(o[26]=r(" 荣誉推出",-1))])])}const S=d(p,[["render",f]]);export{P as __pageData,S as default};
